def f(g):
    # 2 special markers (non-zero, distinct from fill 5). Draw path: from each marker to the other via diagonal steps towards target, painting 5.
    cells=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v not in (0,)]
    m=[(i,j,g[i][j]) for i,j,_ in cells]
    out=[r[:] for r in g]; seen={(0,0)}; 
    while m:
        i,j,c=m.pop(); di=-1 if i==0 else (1 if i>=max(i for _,_,_ in m) else -1); dj=1 if c!=min(x[2] for x in m) else -1
        for step in range(abs(c)):
            ni,nj=i+step*di,j+step*dj
            if 0<=ni<len(out) and 0<=nj<len(out[0]) and out[ni][nj]==0 and (ni,nj) not in seen:
                out[ni][nj]=5; seen.add((ni,nj)); continue
            break
    return out
